select opened_month, sqft_bucket, stddev_sqft, row_count from (select date_trunc('MONTH', opened_date) as opened_month, case when sqft >= 16638 then 'high' when sqft >= 7142 then 'mid' else 'low' end as sqft_bucket, round(stddev(sqft), 2) as stddev_sqft, count(*) as row_count from stores group by date_trunc('MONTH', opened_date), case when sqft >= 16638 then 'high' when sqft >= 7142 then 'mid' else 'low' end) as agg where stddev_sqft >= 71 order by stddev_sqft desc
